SELECT ticket_id, status
FROM support_tickets
WHERE payload ->> 'channel' = 'chat';

SELECT subscription_id
FROM subscriptions
WHERE status = 'active';

SELECT da.invoice_id, MAX(da.attempted_at) AS latest_dunning_attempt_at
FROM dunning_attempts AS da
GROUP BY da.invoice_id;

SELECT alert_id
FROM alerts
WHERE status = 'open';

SELECT customer_id, risk_score
FROM (
    SELECT customer_id, risk_score,
           ROW_NUMBER() OVER (
               PARTITION BY customer_id
               ORDER BY assessed_at DESC, assessment_id DESC
           ) AS rn
    FROM risk_assessments
) AS ranked
WHERE rn = 1;

SELECT customer_id, COUNT(alert_id) FILTER (WHERE status = 'open') AS open_alerts
FROM alerts
GROUP BY customer_id;

SELECT transaction_id
FROM transactions
WHERE (payload #>> '{risk_score}')::NUMERIC >= 80;

SELECT product_id, on_hand_qty, snapshot_at
FROM (
    SELECT product_id, on_hand_qty, snapshot_at,
           ROW_NUMBER() OVER (
               PARTITION BY product_id
               ORDER BY snapshot_at DESC, snapshot_id DESC
           ) AS rn
    FROM inventory_snapshots
) AS latest
WHERE rn = 1;
